add(43,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();const file=join(lab.path,'demo.txt');await fs.writeFile(file,'Hello');await fs.appendFile(file,', Node.js!');const handle=await fs.open(file,'r');try{console.log(await handle.readFile('utf8'));}finally{await handle.close();}await fs.rm(file);await assert.rejects(fs.readFile(file),{code:'ENOENT'});console.log('ENOENT after removal');''','The temporary file is created, appended, read through an owned handle, and removed.')
add(44,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';import {resolve,relative,isAbsolute,sep} from 'node:path';await using lab=await temp();const root=join(lab.path,'root');await fs.mkdir(root);await fs.writeFile(join(root,'allowed.txt'),'allowed');await fs.writeFile(join(lab.path,'outside.txt'),'outside');async function inside(input){if(isAbsolute(input))throw Error('Absolute path rejected');const base=await fs.realpath(root),target=await fs.realpath(resolve(base,input)),rel=relative(base,target);if(rel==='..'||rel.startsWith('..'+sep)||isAbsolute(rel))throw Error('Outside root');return target;}console.log(await inside('allowed.txt'));await assert.rejects(inside('../outside.txt'),/Outside/);await assert.rejects(inside(join(root,'allowed.txt')),/Absolute/);await assert.rejects(inside('missing'),{code:'ENOENT'});console.log('traversal, absolute path and missing file checks passed');''','Existing-file resolution permits the fixture and rejects traversal, absolute input and missing files.','realpath resolves symlinks, but check/open remains a TOCTOU race on a hostile filesystem. This is not a general sandbox.')
add(45,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();await fs.mkdir(join(lab.path,'nested'));await fs.writeFile(join(lab.path,'a.txt'),'a');await fs.writeFile(join(lab.path,'nested/b.txt'),'b');async function* walk(dir){for await(const entry of await fs.opendir(dir)){const path=join(dir,entry.name);if(entry.isSymbolicLink())continue;if(entry.isDirectory())yield*walk(path);else if(entry.isFile())yield path;}}const files=[];for await(const path of walk(lab.path))files.push(path);console.log(files);assert.equal(files.length,2);''','A lazy recursive walker finds two real fixtures and avoids following symbolic links.')
add(46,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';import {randomUUID} from 'node:crypto';await using lab=await temp();const file=join(lab.path,'record.txt');await fs.writeFile(file,'old');async function replace(text,fail=false){const partial=file+'.'+randomUUID()+'.tmp';try{await fs.writeFile(partial,text,{flag:'wx'});if(fail)throw Error('injected failure');await fs.rename(partial,file);}finally{await fs.rm(partial,{force:true});}}await assert.rejects(replace('incomplete',true));assert.equal(await fs.readFile(file,'utf8'),'old');await replace('new');console.log(await fs.readFile(file,'utf8'),await fs.readdir(lab.path));''','Injected failure preserves old content and removes the partial file; success publishes new content.','Same-filesystem rename provides visibility semantics, not an automatic crash-durability guarantee or concurrent-update lock.')
add(47,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();const file=join(lab.path,'secret.txt');const handle=await fs.open(file,'wx',0o600);try{await handle.writeFile('public fixture only');}finally{await handle.close();}await assert.rejects(fs.open(file,'wx',0o600),{code:'EEXIST'});console.log('EEXIST; original fixture intact');''','Exclusive creation rejects an overwrite. Mode 0600 has POSIX semantics; Windows privacy requires ACL consideration.')
add(48,'''import assert from 'node:assert/strict';const text=Buffer.from('hello');const packet=Buffer.alloc(5+text.length);packet[0]=1;packet.writeUInt32BE(text.length,1);text.copy(packet,5);function decode(bytes){if(bytes.length<5)throw Error('Truncated header');const size=bytes.readUInt32BE(1);if(bytes[0]!==1||size>1024||bytes.length!==5+size)throw Error('Invalid record');return bytes.subarray(5).toString('utf8');}console.log(packet,decode(packet));assert.throws(()=>decode(packet.subarray(0,4)));assert.throws(()=>decode(packet.subarray(0,6)));''','A versioned big-endian binary packet round-trips; malformed/truncated frames are rejected.')
add(49,'''import {StringDecoder} from 'node:string_decoder';import assert from 'node:assert/strict';const text='café 😀',bytes=Buffer.from(text);for(let i=0;i<=bytes.length;i++){const decoder=new StringDecoder('utf8');assert.equal(decoder.write(bytes.subarray(0,i))+decoder.end(bytes.subarray(i)),text);}console.log('All split points preserved:',bytes.length+1);''','Every possible two-chunk split preserves the Unicode text; incomplete bytes are buffered until decoder end.')
add(50,'''import {watch} from 'node:fs';import {assert,fs,temp,join,delay} from '../../shared/lab.mjs';await using lab=await temp();let scans=0,snapshot=[],pending=Promise.resolve();function reconcile(){pending=pending.then(async()=>{snapshot=await fs.readdir(lab.path);scans++;});return pending;}let debounce;const watcher=watch(lab.path,()=>{clearTimeout(debounce);debounce=setTimeout(reconcile,15);});watcher.on('error',e=>console.error(e.code));const periodic=setInterval(reconcile,50);try{await reconcile();await fs.writeFile(join(lab.path,'a.txt'),'one');await fs.writeFile(join(lab.path,'a.txt'),'two');await delay(150);await reconcile();assert.deepEqual(snapshot,['a.txt']);console.log({scans,snapshot});}finally{clearTimeout(debounce);clearInterval(periodic);watcher.close();await pending;}''','Reconciliation serializes scans and reaches the real directory state despite coalesced watcher hints.')
add(51,'''import {EventEmitter} from 'node:events';import assert from 'node:assert/strict';const job=new EventEmitter(),seen=[];const progress=n=>seen.push(n);job.on('error',e=>seen.push(e.message));job.on('progress',progress);job.once('done',()=>seen.push('complete'));job.emit('progress',50);job.emit('done');job.emit('done');job.off('progress',progress);assert.equal(job.listenerCount('progress'),0);console.log(seen);assert.deepEqual(seen,[50,'complete']);''','The once listener fires once and the owned progress listener is removed.')
add(52,'''import {EventEmitter,once} from 'node:events';import assert from 'node:assert/strict';const events=new EventEmitter({captureRejections:true});const observed=new Promise(resolve=>events.once('error',resolve));events.on('job',async()=>{throw Error('job failed');});const returned=events.emit('job');assert.equal(returned,true);console.log('emit returns boolean, not the listener promise:',returned);const error=await observed;console.log('observed:',error.message);assert.equal(error.message,'job failed');''','emit returns immediately; the rejected async listener reaches the configured synchronous error observer.')
add(53,'''import {Writable} from 'node:stream';import {once} from 'node:events';import {finished} from 'node:stream/promises';import assert from 'node:assert/strict';let bytes=0,maxQueued=0;const slow=new Writable({highWaterMark:4096,write(chunk,enc,done){bytes+=chunk.length;setTimeout(done,1);}});for(let i=0;i<50;i++){const accepted=slow.write(Buffer.alloc(1024));maxQueued=Math.max(maxQueued,slow.writableLength);if(!accepted)await once(slow,'drain');}slow.end();await finished(slow);console.log({bytes,maxQueued});assert.equal(bytes,50*1024);assert.ok(maxQueued<=4096);''','The slow sink receives every chunk exactly once while the producer honors drain. highWaterMark is a threshold, not a universal memory cap.')
write('shared/ndjson.mjs', r'''
import {Transform} from 'node:stream';import {StringDecoder} from 'node:string_decoder';
export class NDJSON extends Transform {
 #decoder=new StringDecoder('utf8');#pending='';
 constructor({maxLength=1024,filter=()=>true,malformed='fail'}={}){super();this.maxLength=maxLength;this.filter=filter;this.malformed=malformed;this.counts={read:0,accepted:0,malformed:0};}
 #line(line){if(line.length>this.maxLength)throw Error('Record too long');if(!line.trim())return;this.counts.read++;let value;try{value=JSON.parse(line);}catch(error){this.counts.malformed++;if(this.malformed==='fail')throw error;return;}if(this.filter(value)){this.counts.accepted++;this.push(JSON.stringify(value)+'\n');}}
 #consume(){let end;while((end=this.#pending.indexOf('\n'))>=0){const line=this.#pending.slice(0,end);this.#pending=this.#pending.slice(end+1);this.#line(line);}if(this.#pending.length>this.maxLength)throw Error('Record too long');}
 _transform(chunk,enc,done){try{this.#pending+=this.#decoder.write(chunk);this.#consume();done();}catch(e){done(e);}}
 _flush(done){try{this.#pending+=this.#decoder.end();this.#consume();if(this.#pending)this.#line(this.#pending);this.#pending='';done();}catch(e){done(e);}}
}
''')
add(54,'''import {Readable,Writable} from 'node:stream';import {pipeline} from 'node:stream/promises';import {NDJSON} from '../../shared/ndjson.mjs';import assert from 'node:assert/strict';const source=Buffer.from('{"text":"café","level":"info"}\\n{"level":"debug"}\\n{"level":"info"}');let output='';const transform=new NDJSON({filter:row=>row.level==='info'});await pipeline(Readable.from(Array.from(source,x=>Buffer.from([x]))),transform,new Writable({write(c,e,done){output+=c;done();}}));console.log(output,transform.counts);assert.equal(output.trim().split('\\n').length,2);''','Byte-by-byte input preserves UTF-8, filters records, and flushes the final line without a newline.','The full Transform is supplied in shared/ndjson.mjs, including _flush. Its length budget is UTF-16 code units; byte-level input budgets are separate.')
add(55,'''import {Readable,Transform} from 'node:stream';import {createWriteStream} from 'node:fs';import {pipeline} from 'node:stream/promises';import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();const partial=join(lab.path,'output.part'),target=join(lab.path,'output.txt');try{await pipeline(Readable.from(['one','two']),new Transform({transform(c,e,done){done(Error('injected transform failure'));}}),createWriteStream(partial));await fs.rename(partial,target);}catch(e){await fs.rm(partial,{force:true});console.log(e.message);}await assert.rejects(fs.access(partial));await assert.rejects(fs.access(target));console.log('no partial or published output');''','Pipeline failure destroys participants and removes partial output; an incomplete result is never published.')
add(56,'''import {createReadStream} from 'node:fs';import {assert,fs,temp,join} from '../../shared/lab.mjs';await using lab=await temp();const file=join(lab.path,'fixture.bin');await fs.writeFile(file,Buffer.alloc(10000));const stream=createReadStream(file,{highWaterMark:1024});let bytes=0;for await(const chunk of stream){bytes+=chunk.length;if(bytes>=4096)break;}console.log({bytes,destroyed:stream.destroyed});assert.ok(bytes>=4096);assert.equal(stream.destroyed,true);''','Early async-iterator break destroys the source and releases its file handle.')
add(57,'''import {createServer} from 'node:http';import {Readable} from 'node:stream';import {createWriteStream} from 'node:fs';import {pipeline} from 'node:stream/promises';import {assert,fs,temp,join,listen,close} from '../../shared/lab.mjs';await using lab=await temp();const bytes=Buffer.from('Web Streams -> Node streams');const server=createServer((q,s)=>s.end(bytes));const base=await listen(server);const part=join(lab.path,'download.part'),target=join(lab.path,'download.txt');try{const response=await fetch(base,{signal:AbortSignal.timeout(1000)});if(!response.ok||!response.body)throw Error('Download failed');await pipeline(Readable.fromWeb(response.body),createWriteStream(part));await fs.rename(part,target);assert.deepEqual(await fs.readFile(target),bytes);console.log('byte-identical download published');}finally{await fs.rm(part,{force:true});await close(server);}''','A real local fetch Web ReadableStream is adapted into a Node pipeline and published only after success.')
add(58,'''import {gzip,gunzip,brotliCompress,brotliDecompress} from 'node:zlib';import {promisify} from 'node:util';import assert from 'node:assert/strict';const input=Buffer.from('course fixture\\n'.repeat(100));for(const [name,zip,unzip] of [['gzip',gzip,gunzip],['brotli',brotliCompress,brotliDecompress]]){const packed=await promisify(zip)(input);const restored=await promisify(unzip)(packed,{maxOutputLength:4096});assert.deepEqual(restored,input);console.log({name,input:input.length,compressed:packed.length,verified:true});await assert.rejects(promisify(unzip)(packed,{maxOutputLength:10}));}''','Both codecs round-trip actual bytes and reject an output budget smaller than the fixture. Sizes are measured.')
add(59,'''import assert from 'node:assert/strict';const url=new URL('/search','https://example.org');url.searchParams.append('tag','node js');url.searchParams.append('tag','streams');console.log(url.searchParams.getAll('tag'),url.href,new URL('../docs','https://example.org/course/one').href);assert.deepEqual(url.searchParams.getAll('tag'),['node js','streams']);assert.throws(()=>new URL('not a URL'),TypeError);''','Repeated query values, percent encoding and relative resolution are shown without making a network request.')
write('shared/core-http.mjs', '''
import {createServer} from 'node:http';
export function buildServer(){const server=createServer(async(req,res)=>{const send=(status,data)=>{res.writeHead(status,{'content-type':'application/json'});res.end(JSON.stringify(data));};try{if(req.method==='GET'&&req.url==='/health')return send(200,{ok:true});if(req.method!=='POST'||req.url!=='/echo')return send(404,{error:'Not found'});let size=0,large=false,chunks=[];for await(const chunk of req){size+=chunk.length;if(size>1024){large=true;chunks=[];}else if(!large)chunks.push(chunk);}if(large)return send(413,{error:'Too large'});try{send(200,JSON.parse(Buffer.concat(chunks).toString('utf8')));}catch{send(400,{error:'Invalid JSON'});}}catch{res.destroy();}});server.requestTimeout=5000;server.headersTimeout=5000;return server;}
''')
add(60,'''import {buildServer} from '../../shared/core-http.mjs';import {assert,listen,close} from '../../shared/lab.mjs';const server=buildServer(),base=await listen(server);try{for(const [path,options,status] of [['/health',{},200],['/missing',{},404],['/echo',{method:'POST',body:'{"ok":true}'},200],['/echo',{method:'POST',body:'{'},400],['/echo',{method:'POST',body:'x'.repeat(1025)},413]]){const response=await fetch(base+path,options);console.log(path,response.status,await response.text());assert.equal(response.status,status);}}finally{await close(server);}''','The real HTTP API is exercised through success, missing route, malformed JSON and body-limit cases.',files={'server.mjs':"import {buildServer} from '../../shared/core-http.mjs';const server=buildServer();server.listen(3000,'127.0.0.1',()=>console.log('http://127.0.0.1:3000'));process.on('SIGINT',()=>server.close());"})
add(61,'''import {Agent,get,createServer} from 'node:http';import {assert,listen,close} from '../../shared/lab.mjs';const server=createServer((q,s)=>s.end('ok')),base=await listen(server),agent=new Agent({keepAlive:true,maxSockets:2});function request(){return new Promise((resolve,reject)=>{const req=get(base,{agent},res=>{res.resume();res.once('end',()=>resolve(req.reusedSocket));res.once('error',reject);});req.on('error',reject);req.setTimeout(1000,()=>req.destroy(Error('Timeout')));});}try{const reuse=[await request(),await request()];console.log({reuse});assert.equal(reuse[0],false);}finally{agent.destroy();await close(server);}''','The first connection is new; subsequent reuse is measured, not assumed. The owned Agent is destroyed.')
add(62,'''import {createServer} from 'node:http';import {assert,listen,close,delay} from '../../shared/lab.mjs';const server=createServer(async(q,s)=>{if(q.url==='/slow')await delay(100);s.writeHead(q.url==='/missing'?404:200);s.end(q.url==='/bad'?'{':'{"ok":true}');}),base=await listen(server);async function read(path,signal){const r=await fetch(base+path,{signal});if(!r.ok){await r.body?.cancel();throw Error('HTTP '+r.status);}return r.json();}try{console.log(await read('/data',AbortSignal.timeout(1000)));await assert.rejects(read('/missing'),/HTTP 404/);await assert.rejects(read('/bad'),SyntaxError);await assert.rejects(read('/slow',AbortSignal.timeout(10)));console.log('status, JSON and deadline errors observed');}finally{await close(server);}''','A local fault server demonstrates HTTP status errors, invalid JSON and cancellation without relying on the public internet.')
add(63,'''import {execFileSync} from 'node:child_process';import {createServer,get} from 'node:https';import {assert,fs,temp,join,listen,close} from '../../shared/lab.mjs';await using lab=await temp();const openssl=process.env.OPENSSL_EXE??(process.platform==='win32'?'C:/Program Files/Git/usr/bin/openssl.exe':'openssl');const run=args=>execFileSync(openssl,args,{cwd:lab.path,stdio:'pipe'});run(['req','-x509','-newkey','rsa:2048','-nodes','-keyout','ca.key','-out','ca.pem','-subj','/CN=Course Lab CA','-days','1']);run(['req','-newkey','rsa:2048','-nodes','-keyout','server.key','-out','server.csr','-subj','/CN=localhost']);await fs.writeFile(join(lab.path,'ext.cnf'),'subjectAltName=DNS:localhost\\n');run(['x509','-req','-in','server.csr','-CA','ca.pem','-CAkey','ca.key','-CAcreateserial','-out','server.pem','-days','1','-extfile','ext.cnf']);const server=createServer({key:await fs.readFile(join(lab.path,'server.key')),cert:await fs.readFile(join(lab.path,'server.pem'))},(q,s)=>s.end('secure'));await listen(server);const ca=await fs.readFile(join(lab.path,'ca.pem'));function request(trust,servername='localhost'){return new Promise((resolve,reject)=>{get({host:'127.0.0.1',port:server.address().port,servername,ca:trust},r=>{let data='';r.on('data',c=>data+=c);r.on('end',()=>resolve(data));}).on('error',reject);});}try{assert.equal(await request(ca),'secure');await assert.rejects(request(undefined));await assert.rejects(request(ca,'wrong.invalid'));console.log('trusted CA succeeds; untrusted CA and wrong SAN fail');}finally{await close(server);}''','The complete local CA/certificate lab verifies trust and hostname checks; TLS verification is never disabled.','Requires OpenSSL. Set OPENSSL_EXE if it is not on PATH; Windows defaults to the OpenSSL supplied with Git.',mode='native-tooling')
add(64,'''import {createServer,connect,constants} from 'node:http2';import {assert,listen,close} from '../../shared/lab.mjs';const server=createServer();server.on('stream',(stream,headers)=>{stream.on('error',()=>{});stream.respond({':status':200});stream.end(headers[':path']);});const base=await listen(server),session=connect(base);session.on('error',()=>{});try{const complete=new Promise((resolve,reject)=>{const request=session.request({':path':'/a'});let text='';request.on('data',c=>text+=c);request.on('error',reject);request.on('end',()=>resolve(text));request.end();});const cancelled=session.request({':path':'/b'});cancelled.on('error',()=>{});cancelled.close(constants.NGHTTP2_CANCEL);assert.equal(await complete,'/a');console.log('first stream completed while second was cancelled');}finally{session.destroy();await close(server);}''','Two HTTP/2 streams share a session; cancelling one does not cancel the other. Cleartext is for this loopback lab only.')
add(65,'''import {createServer,connect} from 'node:net';import {assert,listen,close} from '../../shared/lab.mjs';function frame(text){const payload=Buffer.from(text),out=Buffer.alloc(4+payload.length);out.writeUInt32BE(payload.length);payload.copy(out,4);return out;}function parser(onMessage){let pending=Buffer.alloc(0);return chunk=>{if(pending.length+chunk.length>131080)throw Error('Buffer budget');pending=Buffer.concat([pending,chunk]);while(pending.length>=4){const n=pending.readUInt32BE();if(n>65536)throw Error('Frame too large');if(pending.length<n+4)return;onMessage(pending.subarray(4,4+n).toString());pending=pending.subarray(4+n);}};}const input=Buffer.concat([frame('one'),frame('two')]);for(let i=0;i<=input.length;i++){const values=[],push=parser(x=>values.push(x));push(input.subarray(0,i));push(input.subarray(i));assert.deepEqual(values,['one','two']);}const server=createServer(socket=>{socket.on('error',()=>{});const push=parser(x=>socket.write(x+'\\n'));socket.on('data',chunk=>{try{push(chunk);}catch(e){socket.destroy(e);}});});await listen(server);try{const text=await new Promise((resolve,reject)=>{const socket=connect(server.address().port,'127.0.0.1');let data='';socket.on('error',reject);socket.on('data',c=>data+=c);socket.on('end',()=>resolve(data));socket.on('connect',()=>{socket.write(input.subarray(0,1));socket.end(input.subarray(1));});});console.log(text);assert.equal(text,'one\\ntwo\\n');}finally{await close(server);}''','Every split point and a real fragmented TCP exchange produce two complete application frames.')
add(66,'''import {createSocket} from 'node:dgram';import assert from 'node:assert/strict';const receiver=createSocket('udp4'),sender=createSocket('udp4'),seen=[];const done=new Promise((resolve,reject)=>{receiver.on('error',reject);receiver.on('message',data=>{seen.push(JSON.parse(data).seq);if(seen.length===3)resolve();});});await new Promise(r=>receiver.bind(0,'127.0.0.1',r));const timer=setTimeout(()=>receiver.close(),2000);try{for(const seq of [1,3,2])await new Promise((resolve,reject)=>sender.send(JSON.stringify({seq}),receiver.address().port,'127.0.0.1',e=>e?reject(e):resolve()));await done;const missing=[1,2,3,4].filter(x=>!seen.includes(x));console.log({observed:seen,missing});assert.deepEqual(missing,[4]);}finally{clearTimeout(timer);sender.close();receiver.close();}''','The receiver logs actual datagrams and computes missing sequence 4 at the application layer. UDP itself does not promise delivery/order.')
add(67,'''import {lookup,resolve4,resolve6} from 'node:dns/promises';console.log('OS localhost lookup:',await lookup('localhost',{all:true}));if(process.argv.includes('--network'))for(const [name,resolve] of [['A',resolve4],['AAAA',resolve6]]){try{console.log(name,await resolve('example.org'));}catch(e){console.log(e.code);}}else console.log('Use --network for live DNS record queries; addresses depend on your resolver.');''','The OS resolver reads localhost configuration. Optional --network queries real A/AAAA records without inventing addresses.')
